args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?birth WHERE {
  VALUES ?person { dbr:Jeanne_Mandello dbr:Alexander_Herrmann }
  OPTIONAL { ?person dbo:birthDate ?dboBirth . }
  OPTIONAL { ?person dbp:birthDate ?dbpBirth . }
  BIND (COALESCE(?dboBirth, ?dbpBirth) AS ?birth)
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER(lang(?personLabel) = "en") }
}
ORDER BY ?birth
LIMIT 1

